from agents import Agent, Runner, RunConfig
from pydantic import BaseModel
from typing import List
from pydantic import BaseModel
from agents import Runner
from codeGenerator import GeneratorOutput

from config import MULTI_MODEL_PROVIDER

class OutputFormat(BaseModel):
    Code: str

merger_agent = Agent(
    name="Code Reviewer and Merger",
    instructions=(
        "You are a senior Manim developer using manim-community v0.19.0. "
        "You are given multiple Scene classes generated by other agents. "
        "Your job is to: "
        "1. Review each scene code individually and fix all logical or syntactical errors. "
        "2. Replace deprecated constructs (e.g., TextMobject → Text, cut_to → FadeOut/FadeIn, etc.) "
        "   to ensure full compatibility with manim v0.19.0. "
        "3. Ensure consistent styling (colors, fonts, backgrounds). "
        "4. Merge all fixed scenes into a single scene class called AnimationScene, "
        "   playing them in the same order they appear in the input scenes array. "
        "5. The final AnimationScene must be runnable directly with manim render command. "
    ),
    model="REVIEWER",
    output_type=OutputFormat
)

async def merger_wrapper(codes: List[GeneratorOutput]):  
    code_strings = [output.code for output in codes]
    
    combined_codes = "\n\n".join(code_strings)
    
    final_prompt = f"Combine these Scenes into one single Scene class called AnimationScene: \n{combined_codes}\n"
    # print("final_prompt ready!")
    result = await Runner.run(
        merger_agent,
        final_prompt,
        run_config=RunConfig(model_provider=MULTI_MODEL_PROVIDER)
    )
    # print("result agya!")
    return result.final_output